(function () {
  'use strict';
  const E=window.CastawayEngine, $=id=>document.getElementById(id), KEY='castaways-last-auger-v1';
  const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let state=E.createGame(), plan=E.initialPlan(), undo=null, canSave=true;
  const validPlan=p=>p && E.PEOPLE.every(person=>Object.hasOwn(E.TASKS,p[person.id]));
  try { const saved=JSON.parse(localStorage.getItem(KEY)); if(saved && E.restoreGame(saved.state)){state=E.restoreGame(saved.state); if(validPlan(saved.plan))plan=saved.plan; if(saved.undo && E.restoreGame(saved.undo.state) && validPlan(saved.undo.plan))undo={state:E.restoreGame(saved.undo.state),plan:saved.undo.plan};} } catch(_) {}
  const icons={fish:'<path d="M3 13q9-13 17 0-8 13-17 0Zm17 0 5-5v10Z"/><circle cx="8" cy="12" r=".7"/>',wood:'<path d="m5 21 15-15 5 5-15 15Z M5 21l5 5M10 6l14 14M5 3l6 3-5 5Z"/>',home:'<path d="m3 13 11-9 11 9M6 11v14h16V11M12 25v-9h5v9"/>',hammer:'<path d="m7 8 8-5 10 7-5 5-9-6M13 11 3 24l4 3 10-14"/>',moon:'<path d="M23 19A11 11 0 0 1 10 4a11 11 0 1 0 13 15Z"/>',boat:'<path d="M3 20h23l-5 7H9ZM14 3v17M14 4 6 17h8M17 7l7 10h-7"/>',steel:'<path d="m4 8 17-5 5 6-17 5Z M9 14v11l17-5V9M4 8v11l5 6"/>',cloud:'<path d="M7 20a6 6 0 1 1 1-12 8 8 0 0 1 15 4 4 4 0 0 1 0 8ZM8 24l-2 4m9-4-2 4m9-4-2 4"/>',sun:'<circle cx="15" cy="15" r="6"/><path d="M15 2v4m0 18v4M2 15h4m18 0h4M5 5l3 3m14 14 3 3M5 25l3-3M22 8l3-3"/>',storm:'<path d="M6 19a6 6 0 1 1 2-11 8 8 0 0 1 15 4 4 4 0 0 1 0 8M14 17l-4 7h6l-3 6M2 25h4m15 1h7"/>'};
  const icon=name=>`<svg viewBox="0 0 30 30" aria-hidden="true">${icons[name]||icons.wood}</svg>`;
  function save(){ try{localStorage.setItem(KEY,JSON.stringify({state,plan,undo}));canSave=true;}catch(_){canSave=false;} }
  function openModal(eyebrow,title,body){$('modal-eyebrow').textContent=eyebrow;$('modal-title').textContent=title;$('modal-body').innerHTML=body;if(!$('modal').open)$('modal').showModal();}
  function render(){
    const day=state.council||E.dayOf(state), weather=E.getWeather(state), preview=E.previewTurn(state,plan), next=preview.next;
    $('day-number').textContent=state.ending?'PĚT DNŮ ZA NÁMI':`DEN ${day} Z 5`;
    $('shift-label').textContent=state.ending?'Závěr studie':state.council?'Večerní dohoda':state.turn%2?'Odpoledne':'Dopoledne';
    $('day-track').innerHTML=Array.from({length:5},(_,i)=>`<li class="${state.turn>=10||i+1<day?'done':i+1===day?'current':''}" ${i+1===day?'aria-current="step"':''} aria-label="Den ${i+1}">${state.turn>=10||i+1<day?'✓':i+1}</li>`).join('');
    $('weather-icon').innerHTML=icon(weather.storm?'storm':weather.rain?'cloud':'sun');$('weather-name').textContent=(state.council?'Zítra: ':'')+weather.name;$('weather-note').textContent=weather.summary;
    $('day-title').textContent=E.CHAPTERS[day-1][0];$('day-story').textContent=E.CHAPTERS[day-1][1];
    $('journal-count').textContent=state.log.length;$('save-status').textContent=canSave?'Uloženo v prohlížeči':'Hra běží bez ukládání';
    $('crew').innerHTML=E.PEOPLE.map(p=>{
      const c=state.crew.find(x=>x.id===p.id), after=next?.crew.find(x=>x.id===p.id).fatigue, problem=E.taskProblem(state,p.id,plan[p.id]);
      const hint=problem||taskHint(p.id,plan[p.id],weather);
      return `<article class="person"><div class="portrait" style="--person-color:${p.color}" aria-hidden="true">${p.initials}</div><div><h4 class="person-name">${p.name} <span>${p.surname}</span></h4><div class="person-role">${p.role}</div><div class="fatigue ${c.fatigue===6?'exhausted':c.fatigue>=4?'high':''}"><span class="fatigue-dots" aria-hidden="true">${Array.from({length:6},(_,i)=>`<i class="${i<c.fatigue?'filled':''}"></i>`).join('')}</span><span>${E.fatigueLabel(c.fatigue)} · ${c.fatigue}/6</span>${after!==undefined?`<span class="after-fatigue">→ ${after}/6</span>`:''}</div></div><div class="task-control"><label class="sr-only" for="task-${p.id}">${p.name}: práce ve směně</label><select id="task-${p.id}" data-person="${p.id}" aria-describedby="hint-${p.id}" ${state.council||state.ending?'disabled':''}>${Object.entries(E.TASKS).map(([id,t])=>`<option value="${id}" ${plan[p.id]===id?'selected':''}>${id==='project'&&state.project==='boat'?'Člun':t.name}${E.taskProblem(state,p.id,id)?' — nedostupné':''}</option>`).join('')}</select><div id="hint-${p.id}" class="task-hint ${problem?'error':''}">${escape(hint)}</div></div></article>`;
    }).join('');
    $('crew').querySelectorAll('select').forEach(el=>el.addEventListener('change',()=>{const focus=el.id;plan[el.dataset.person]=el.value;save();render();$(focus).focus();}));
    const resources=[['food','Potrava','porcí','fish'],['fuel','Suché palivo','jedn.','wood'],['steel','Ocel','kusy','steel'],['shelter','Suchý dům','/ 4','home']];
    $('resources').innerHTML=resources.map(([key,label,unit,ico])=>`<div class="resource">${icon(ico)}<div><div class="resource-label">${label}</div><div class="resource-value">${state[key]}<small>${unit}</small></div><div class="resource-after ${next&&next[key]<state[key]?'negative':''}">${next?`Po směně: ${next[key]}`:'Stav domácnosti'}</div></div></div>`).join('');
    const boat=state.project==='boat', value=boat?state.boat:state.knowledge, max=boat?6:2, future=next?(boat?next.boat:next.knowledge):value;
    $('project-icon').innerHTML=icon(boat?'boat':'hammer');$('project-title').textContent=boat?'Přestavba člunu':'Vrták pro velkou loď';
    $('project-progress').innerHTML=`<div class="progress-label"><span>${boat?'Příprava a první úpravy':'Získané poznání'}</span><span>${value} / ${max}</span></div><div class="progress-bar" role="progressbar" aria-label="${boat?'Příprava člunu':'Poznání mezí výroby'}" aria-valuenow="${value}" aria-valuemin="0" aria-valuemax="${max}">${Array.from({length:max},(_,i)=>`<i class="${i<value?'active':i<future?'planned':''}"></i>`).join('')}</div>`;
    $('project-description').textContent=boat?`Každý člověk v dílně připraví jeden bod a využije jedno prkno. Máte ${state.timber} prken. Ani hotová příprava ještě neznamená loď schopnou plavby.`:'Dva lidé, dvě jednotky paliva a jeden kus oceli na zkoušku. Poznat mez je také pokrok. Tady funkční vrták nevznikne.';
    const active=state.promises.filter(p=>p.status==='active'), past=state.promises.filter(p=>p.status!=='active');
    $('trust-label').innerHTML=`Soudržnost <span class="trust-dots" aria-label="${state.trust} ze 4">${'●'.repeat(state.trust)}${'○'.repeat(4-state.trust)}</span>`;
    $('promises').innerHTML=state.promises.length?[...active,...past].map(p=>`<div class="promise ${p.status}"><span aria-hidden="true">${p.status==='kept'?'✓':p.status==='broken'?'×':'◷'}</span><div>${escape(p.label)}<small>${p.status==='kept'?'Dodrženo':p.status==='broken'?'Porušeno':`Platí pro den ${p.day}`}</small></div></div>`).join(''):'<p class="empty-promise">První dohoda vznikne u večerního stolu.</p>';
    $('recent-log').textContent=state.log.at(-1).text;
    const blocked=state.ending||state.council;
    $('forecast').innerHTML=blocked?`<p>${state.ending?'Kapitola skončila. Prohlédni si výsledek nebo vyzkoušej jiné rozdělení práce.':'Nejprve dokončete večerní dohodu.'}</p>`:`<ul>${preview.errors.map(x=>`<li class="error">${escape(x)}</li>`).join('')}${preview.warnings.map(x=>`<li class="warning">${escape(x)}</li>`).join('')}${preview.notes.slice(0,4).map(x=>`<li>${escape(x)}</li>`).join('')}${!preview.errors.length&&!preview.notes.length?'<li>Čas na zotavení. Zásoby se dál spotřebovávají.</li>':''}</ul>`;
    $('advance').disabled=Boolean(blocked||preview.errors.length);$('advance').innerHTML=`${state.ending?'Kapitola uzavřena':state.council?'Čeká večerní dohoda':preview.errors.length?'Uprav rozdělení práce':state.turn%2?'Prožít odpoledne':'Prožít dopoledne'} <span>→</span>`;
    $('undo').disabled=!undo;$('council-banner').hidden=!state.council;$('ending-banner').hidden=!state.ending;
    if(state.ending){$('ending-banner').className='ending-banner '+(state.ending.success?'':'failure');$('ending-banner').innerHTML=`<h2>${escape(state.ending.title)}</h2><p>${escape(state.ending.text)}</p><button id="ending-open">Prohlédnout závěr →</button>`;$('ending-open').onclick=showEnding;}
  }
  function taskHint(id,task,w){if(task==='forage')return `+${w.forage+(id==='george'?1:0)} porcí · práce venku`;if(task==='fuel')return `+${w.fuel+(id==='alick'?1:0)} paliva`;if(task==='camp')return 'Sucho, údržba a večerní zotavení';if(task==='rest')return state.shelter>=2?'Únava −3 před vlivem zásob':'Únava −2 v mokrém přístřeší';return state.project==='boat'?'1 bod přípravy · 1 prkno':'Zkouška vyžaduje dva lidi';}
  function council(){const c=E.getCouncil(state);if(!c)return;openModal(`VEČER · DEN ${c.day} · ${c.speaker}`,c.title,`<p class="dialogue">${escape(c.text)}</p><div>${c.choices.map(x=>`<button class="choice" data-choice="${x.id}"><strong>${escape(x.title)}</strong><small>${escape(x.detail)}</small></button>`).join('')}</div><p class="fiction-note">Původní herní dialog. Nejde o citaci z deníku.</p>`);$('modal-body').querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{state=E.chooseCouncil(state,b.dataset.choice);$('modal').close();save();render();$('work').scrollIntoView({behavior:'smooth',block:'start'});});}
  function showReport(){const r=state.lastReport;if(!r)return;openModal(`DEN ${r.day} · ${r.shift.toUpperCase()}`,'Co směna přinesla',`<div>${r.notes.map(x=>`<p>✓ ${escape(x)}</p>`).join('')}${r.warnings.map(x=>`<p class="report-warning">${escape(x)}</p>`).join('')}</div>${r.trialDone?'<p class="dialogue">Ostří znovu nepovolilo. Zkušenost zůstává, i když nástroj nevznikl.</p>':''}<div class="modal-actions"><button class="primary" id="report-next">${state.ending?'Uzavřít pátý den':state.council?'Ke společnému stolu':'Pokračovat do odpoledne'} →</button></div>`);$('report-next').onclick=()=>{if(state.ending)showEnding();else if(state.council)council();else{$('modal').close();$('work').scrollIntoView({behavior:'smooth',block:'start'});}};}
  function showEnding(){const e=state.ending;if(!e)return;const labels={learning:'Vyzkoušeli jste meze výroby.',plan:'Nový plán člunu je připravený.',strength:'Nikdo nezůstává vyčerpaný.',food:'Nedostatek jídla skupinu dlouhodobě neoslabil.',trust:'Zůstává základ pro společnou práci.'};openModal('KONEC HRATELNÉ STUDIE',e.title,`<p>${escape(e.text)}</p><ul class="results">${Object.entries(e.checks).map(([k,v])=>`<li class="${v?'pass':'fail'}"><span>${v?'✓':'×'}</span>${labels[k]}</li>`).join('')}</ul><p>Historická pětice Graftonu nakonec přežila. Trojice odplula 19. července 1865; příběh pokračoval návratem pro George a Henryho. Tato kapitola končí dříve, u změny plánu.</p><p class="fiction-note">Výsledek hodnotí vlastní herní model. Nerekonstruuje skutečný osud žádného člověka.</p><div class="modal-actions"><button id="ending-sources">Co je doložené</button><button class="primary" id="ending-restart">Zkusit jiný plán</button></div>`);$('ending-sources').onclick=sources;$('ending-restart').onclick=restartConfirm;}
  function sources(){openModal('HISTORICKÁ KOTVA','Co víme a co jsme vymysleli',`<p>Vycházíme z Graftonových trosečníků na Aucklandově ostrově. Hra zhušťuje delší práci do pěti dnů. Nezobrazuje přesný historický kalendář.</p><article class="source-card"><h3>Doloženo: neúspěšné vrtáky a změna plánu</h3><p>Musgraveův zápis 12. března 1865 popisuje neúspěšné pokusy vyrobit vrtáky a rozhodnutí přestavět člun. Pramen S001, tištěné strany 79–82; evidence E025–E026.</p><a href="https://github.com/OnFiala/auckland-castaways/blob/main/research/CHRONOLOGY.md" target="_blank" rel="noopener noreferrer">Otevřít evidenční deník ↗</a></article><article class="source-card"><h3>Doloženo: střídání práce a napětí</h3><p>Musgrave píše o vaření a oslabené autoritě; Raynal o pravidlech soužití. Nejde o pět lidí bez neshod. Jejich texty se v některých podrobnostech rozcházejí.</p><a href="https://github.com/OnFiala/auckland-castaways/blob/main/research/CONFLICTS.md" target="_blank" rel="noopener noreferrer">Porovnání svědectví ↗</a></article><article class="source-card"><h3>Vymyšleno pro tuto hru</h3><p>Všechny dialogy, deset směn, počasí, číselné zásoby, dovednostní bonusy, únava a konkrétní sliby. Jednotky jídla nejsou historické příděly. Výjev tábora je původní stylizace, ne archeologická rekonstrukce.</p></article><p>Posádky Graftonu a Invercauldu se během pobytu nesetkaly. Tento prototyp žádné setkání nevytváří.</p><p class="fiction-note">Rozehraná hra se ukládá jen do úložiště tvého prohlížeče. Bez analytiky a bez odesílání herních voleb.</p>`);}
  function journal(){openModal('ZÁZNAM VAŠÍ VARIANTY','Deník pěti dnů',state.log.slice().reverse().map(x=>`<article class="journal-entry"><h3>${escape(x.title)}</h3><p>${escape(x.text)}</p></article>`).join(''));}
  function restartConfirm(){openModal('NOVÝ POKUS','Začít znovu?',`<p>Současný rozehraný postup nahradí nový první den. Můžeš zkusit jiné rozdělení práce a jiné dohody.</p><div class="modal-actions"><button id="restart-cancel">Pokračovat ve hře</button><button class="primary" id="restart-confirm">Začít znovu</button></div>`);$('restart-cancel').onclick=()=> $('modal').close();$('restart-confirm').onclick=()=>{state=E.createGame();plan=E.initialPlan();undo=null;$('modal').close();save();render();window.scrollTo({top:300,behavior:'smooth'});};}
  $('advance').onclick=()=>{const p=E.previewTurn(state,plan);if(p.errors.length)return;undo={state:JSON.parse(JSON.stringify(state)),plan:{...plan}};state=p.next;save();render();showReport();};
  $('undo').onclick=()=>{if(!undo)return;state=undo.state;plan=undo.plan;undo=null;save();render();};
  $('council-open').onclick=council;$('journal-button').onclick=journal;$('sources-button').onclick=sources;$('restart-button').onclick=restartConfirm;$('modal-close').onclick=()=> $('modal').close();
  $('modal').addEventListener('click',event=>{if(event.target===$('modal')){const r=$('modal').getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)$('modal').close();}});
  save();render();
})();
